import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});
 await new Promise(r=>setTimeout(r,400));
 const result=await call('Runtime.evaluate',{awaitPromise:true,returnByValue:true,expression:`(async()=>{
 const {ArenaSoundEffects,ARENA_SOUND_FILES}=await import('/src/js/toy-room/ArenaSoundEffects.js');
 const effects=new ArenaSoundEffects(), ctx=new AudioContext();await ctx.resume();await effects.preload(ctx);
 const check=(v,s)=>{if(!v)throw Error(s);};check(effects.buffers.size===10,'Dez MP3s decodificados');
 const analysis=[];
 for(const [file,b] of effects.buffers){const d=b.getChannelData(0);let peak=0,sum=0,first=-1,last=0;for(let i=0;i<d.length;i++){const a=Math.abs(d[i]);peak=Math.max(peak,a);sum+=a*a;if(a>.025){if(first<0)first=i;last=i;}}analysis.push({file,duration:b.duration,peak,rms:Math.sqrt(sum/d.length),first:first/b.sampleRate,last:last/b.sampleRate});}
 console.log(JSON.stringify(analysis)); const renders=[];
 for(const event of Object.keys(ARENA_SOUND_FILES)){
  const offline=new OfflineAudioContext(2,96000,48000);const fx=new ArenaSoundEffects();fx.buffers=effects.buffers;
  check(fx.play(offline,offline.destination,event),'Evento amostrado '+event);
  const rendered=await offline.startRendering();let peak=0;for(const channel of [0,1])for(const v of rendered.getChannelData(channel))peak=Math.max(peak,Math.abs(v));
  if(!(peak>.005 && peak<1))throw Error('Sinal inválido '+event+' pico='+peak+' análise='+JSON.stringify(analysis));check(fx.voices.size===0,'Liberação de voz '+event);renders.push({event,peak});
 }
 for(const level of [0,.25,1]) {
  const offline=new OfflineAudioContext(2,96000,48000),fx=new ArenaSoundEffects(),master=offline.createGain();fx.buffers=effects.buffers;master.gain.value=level;master.connect(offline.destination);fx.play(offline,master,'player_attack');
  const b=await offline.startRendering();let peak=0;for(const channel of [0,1])for(const v of b.getChannelData(channel))peak=Math.max(peak,Math.abs(v));
  const reference=renders.find(r=>r.event==='player_attack').peak;check(Math.abs(peak-reference*level)<.00001,'Ganho mestre proporcional '+level);
 }
 effects.play(ctx,ctx.destination,'robot_walk');const robot=effects.voices.get('robot_move');effects.play(ctx,ctx.destination,'robot_walk');check(effects.voices.get('robot_move')===robot,'Ruído não reinicia a cada passo');
 effects.play(ctx,ctx.destination,'robot_laser');effects.play(ctx,ctx.destination,'robot_hit');check(effects.voices.size===0,'Dano interrompe caudas do robô');
 effects.play(ctx,ctx.destination,'train_charge');effects.play(ctx,ctx.destination,'train_steam');check(effects.voices.size===1,'Um ataque por personagem');effects.play(ctx,ctx.destination,'enemy_return');check(effects.voices.size===0,'Troca interrompe caudas');
 const originalDecode=AudioContext.prototype.decodeAudioData;let decoded=0;
 AudioContext.prototype.decodeAudioData=async function(...args){const b=await originalDecode.apply(this,args);decoded++;return b;};
 const sources=[];const originalSource=AudioContext.prototype.createBufferSource;
 AudioContext.prototype.createBufferSource=function(){const s=originalSource.call(this);sources.push(s);return s;};
 const {createAudioSystem}=await import('/src/js/audio.js');const audio=createAudioSystem();audio.initAudio();
 for(let i=0;i<100 && decoded<10;i++)await new Promise(r=>setTimeout(r,50));check(decoded===10,'Pré-carga pública completa');
 for(const event of Object.keys(ARENA_SOUND_FILES)){const n=sources.length;audio.playArenaSound(event);check(sources.length===n+1,'API pública usa MP3 '+event);}
 let n=sources.length;audio.setMuted(true);audio.playArenaSound('player_attack');check(sources.length===n,'Mudo bloqueia novas vozes');audio.setMuted(false);audio.pauseMusic();audio.playArenaSound('player_attack');check(sources.length===n,'Pausa bloqueia novas vozes');audio.resumeMusic();audio.playArenaSound('player_attack');check(sources.length===n+1,'Retoma novos efeitos');audio.pauseMusic();audio.startToyRoomMusic();n=sources.length;audio.playArenaSound('player_attack');check(sources.length===n+1,'Entrada na sala encerra pausa da abertura');audio.clearActiveSounds();audio.stopAllAudio();
 AudioContext.prototype.decodeAudioData=originalDecode;AudioContext.prototype.createBufferSource=originalSource;
 await audio.getAudioContext().close();await ctx.close();return {analysis,renders,checks:'Decodificação, API pública, deduplicação, interrupção, mudo, pausa, retomada e liberação aprovados'};
})()`});
 if(result.result?.exceptionDetails)throw Error(JSON.stringify(result.result.exceptionDetails));
 assert.ok(result.result?.result?.value,'Resultado do navegador');console.log(JSON.stringify(result.result.result.value,null,2));
} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
